fn solve(n: i8, k: i8) -> Vec<i8> {
    // If nothing is selected or everything is selected,
    // there can be no "good" unselected items.
    if k == 0 || k == n {
        return vec![0, 0];
    }

    // Otherwise at least one "good" unselected item is possible:
    let x_min = 1;

    // The maximum possible good unselected items is bounded by
    // the total unselected (n - k) and by twice the selected (2 * k).
    // We use saturating_mul to avoid overflow when computing 2 * k.
    let unselected = n - k;
    let two_k = k.saturating_mul(2);
    let x_max = unselected.min(two_k);

    vec![x_min, x_max]
}

